  ui_story_31050201_57_dialog_content = "<color=#FFB400>Sulfur</color>? Perasaanku tidak enak tentang hal ini...",
  ui_story_31050201_58_dialog_content = "Mana mungkin Joanie Boom memperdaya Eve agar berperan dalam rencananya... Jangan sampai aku lengah di dekatnya, apa pun yang terjadi.",
