  ui_story_31050201_64_dialog_content = "<color=#e8d9bb>Sekantong bubuk mesiu jatuh ke lantai.</color>",
  ui_story_31050201_65_dialog_content = "Kamu memang datang untuk mengambil barang ini.",
  ui_story_31050201_66_dialog_content = "A-aku bisa jelaskan...",
  ui_story_31050201_67_dialog_content = "Ini bukan mainan untuk anak-anak, Eve! Apakah Joanie Boom menyuruhmu melakukan ini?",
  ui_story_31050201_68_dialog_content = "Pasti dia bilang ini hanya mainan yang tidak berbahaya... Jadi, dia mengirimmu untuk mengambilnya karena dia tidak diizinkan masuk kemari!",
  ui_story_31050201_69_dialog_content = "Bukan begitu! Joanie Boom bukan orang semacam itu...",
  ui_story_31050201_70_dialog_content = "Kamu terlalu naif. Dia sering melanggar, Eve...",
  ui_story_31050201_71_dialog_content = "Jika kamu mencari sesuatu yang baru dan seru, aku bisa meminta Vice untuk membawakannya dari Illumina.",
  ui_story_31050201_72_dialog_content = "Lalu, jika kamu mau mainan baru, kita bisa meminta Carleen...",
  ui_story_31050201_73_dialog_content = "Apa pun itu, seharusnya kamu tidak memercayai apa pun perkataan Joanie Boom!",
  ui_story_31050201_74_dialog_content = "Jika kamu memercayainya, mungkin kita semua berada dalam bahaya!",
  ui_story_31050201_75_dialog_content = "Sama sekali bukan itu! Justru aku... Akulah yang menyuruhnya melakukannya!",
