  ui_story_31050201_78_dialog_content = "Kamu hampir membuatku terkena serangan jantung...",
  ui_story_31050201_79_option_content = "Dia menyuruhmu berkata begitu?!",
  ui_story_31050201_80_dialog_content = "Tidak! Berhentilah menuduh Joanie seperti itu!",
  ui_story_31050201_81_dialog_content = "Aku sama sekali tidak percaya kamu adalah dalangnya.",
