  ui_story_31050201_83_dialog_content = "Tidak, tunggu... Biar kujelaskan!",
  ui_story_31050201_84_dialog_content = "Kami tidak berbuat sesuatu yang membahayakan!",
  ui_story_31050201_85_dialog_content = "Aku tahu kamu gadis yang baik, Eve...",
  ui_story_31050201_86_dialog_content = "Namun, membuat bom itu sama sekali tidak aman, terutama di sini!",
  ui_story_31050201_87_dialog_content = "Bukan saja ini membahayakan kamu dan orang-orang di sekitarmu, tetapi juga seluruh Colossus.",
  ui_story_31050201_88_dialog_content = "Ini bukan bom...",
  ui_story_31050201_89_dialog_content = "Terlebih lagi, ini bukanlah hal yang bisa ditangani anak kecil sepertimu, dan... Apa?",
  ui_story_31050201_90_dialog_content = "Aku... Aku hanya ingin Joanie membantuku membuat <color=#FFB400>kembang api</color> untuk Dawn...!",
