  ui_story_31050201_94_dialog_content = "Baiklah, setiap kali ada hari libur di desa, kami akan menyalakan kembang api untuk merayakannya!",
  ui_story_31050201_95_dialog_content = "Pada hari libur itu, kami akan duduk bersama keluarga dan makan kudapan sembari menonton kembang api!",
  ui_story_31050201_96_dialog_content = "Saat itu, aku akan duduk di pangkuan orang tuaku, dan Sinsa akan mengupaskan jeruk untuk kumakan!",
  ui_story_31050201_97_dialog_content = "Semua cahaya indah itu meledak di langit malam, kemudian berguguran seperti ribuan bintang jatuh... Rasanya aku ingin membuat permintaan pada setiap bintang itu.",
  ui_story_31050201_98_dialog_content = "Waktu itu sungguh membahagiakan...",
  ui_story_31050201_99_dialog_content = "Jadi, setiap kali melihat kembang api, aku mengingat semua wajah bahagia saat itu.",
  ui_story_31050201_100_option_content = "Terdengar seperti saat-saat yang indah.",
  ui_story_31050201_101_dialog_content = "\"Kembang api meletus di langit malam\"... Aku juga ingin melihat yang seperti itu.",
  ui_story_31050201_102_dialog_content = "Iya, 'kan? Aku tahu tidak ada seorang pun yang bisa menolak kembang api!",
  ui_story_31050201_103_option_content = "Terdengar... Bagus?",
  ui_story_31050201_104_dialog_content = "Hanya \"bagus\"?! Kamu sudah pernah lihat kembang api atau belum? Kamu pasti mengerti jika sudah!",
  ui_story_31050201_105_dialog_content = "Iya, 'kan? Aku tahu tidak ada seorang pun yang bisa menolak kembang api!",
  ui_story_31050201_106_dialog_content = "Entah bagaimana kamu meyakinkanku.",
  ui_story_31050201_107_dialog_content = "Percayalah padaku! Aku pernah bilang pada <color=#FFB400>Dawn</color> soal kembang api juga!",
  ui_story_31050201_108_dialog_content = "Setiap kali dia mendengarku membicarakannya, raut wajah kesedihan dan kecemburuan tersirat di wajahnya...",
  ui_story_31050201_109_dialog_content = "Namun, setiap kali aku bertanya kepadanya tentang itu, dia hanya akan bilang bahwa tidak ada yang istimewa...",
  ui_story_31050201_110_dialog_content = "Aku tahu dia ingin melihatnya, tetapi tidak mau membuatku sedih dengan mengungkit masa lalu...",
  ui_story_31050201_111_dialog_content = "Namun, situasinya kini berbeda! Kamu akan membantuku, 'kan...?",
  ui_story_31050201_112_dialog_content = "Yah, apa boleh buat kalau kamu memberiku raut wajah seperti itu...",
  ui_story_31050201_113_option_content = "Bagaimana bisa aku menolak?",
  ui_story_31050201_114_dialog_content = "Baiklah... Selama tidak membahayakan Colossus, aku akan mengizinkannya. Namun, kalian berdua harus berhati-hati agar tidak terluka!",
  ui_story_31050201_115_dialog_content = "Ya! Kami akan berhati-hati, janji! Kami juga sudah punya rencana!",
  ui_story_31050201_116_dialog_content = "S-sungguh...? Tiba-tiba aku mulai khawatir...",
  ui_story_31050201_117_dialog_content = "Aku juga mulai khawatir.",
  ui_story_31050201_114_option_content = "Aku juga masih belum yakin...",
  ui_story_31050201_119_dialog_content = "Aku berjanji kami tidak akan menyakiti Soroz dengan cara apa pun! Aku bersumpah!",
  ui_story_31050201_120_dialog_content = "Soroz bukan satu-satunya yang dalam bahaya. Keselamatanmu juga penting.",
  ui_story_31050201_121_dialog_content = "*Berdesah* Aku masih sedikit khawatir, tapi karena ini Eve...",
  ui_story_31050201_122_dialog_content = "Omong-omong, untuk apa membuat kembang api untuk Dawn?",
  ui_story_31050201_123_dialog_content = "Baiklah... Dawn sahabatku, dan dia selalu mengawasiku! Bahkan selama bagian terburuk dari hidup kami, dia menjagaku tetap hangat dan aman...",
  ui_story_31050201_124_dialog_content = "Namun, kalau dipikir-pikir, aku belum berbuat apa pun untuknya...",
  ui_story_31050201_125_dialog_content = "Jadi, kupikir kali ini, aku akan memberinya hal <color=#FFB400>terhangat</color> yang bisa kupikirkan!",
  ui_story_31050201_126_dialog_content = "Jadi, aku pergi untuk meminta bantuan Joanie, tetapi dia bilang kamu melarangnya masuk ke ruang penyimpanan... Itu sebabnya aku...",
  ui_story_31050201_127_dialog_content = "Itu benar, ya...",
  ui_story_31050201_128_dialog_content = "Itu sebabnya aku datang kemari! Untuk mengambil semua yang dibutuhkan Joanie dalam pembuatan kembang api!",
  ui_story_31050201_129_dialog_content = "(Lagi pula, Joanie cukup berbahaya. Dia bahkan merekrut seorang anak untuk membantunya kali ini...)",
  ui_story_31050201_130_dialog_content = "Koreksi aku jika salah, tetapi... Bukankah Dawn <color=#FFB400>buta</color>?",
  ui_story_31050201_131_dialog_content = "Apa gunanya membuat kembang api untuknya jika dia tidak bisa melihatnya...?",
  ui_story_31050201_132_dialog_content = "Aku sudah memikirkannya juga. Aku merasa itu hanyalah angan-angan...",
  ui_story_31050201_133_dialog_content = "Aku juga khawatir Dawn akan berpikir itu tidak ada gunanya...",
  ui_story_31050201_134_dialog_content = "Namun, kemudian, kupikir... Kamu tidak perlu melihat sesuatu yang membuat semua orang senang untuk merasakan hal yang sama!",
  ui_story_31050201_135_dialog_content = "*Berdesah* Karena kamu bilang begitu, Eve...",
  ui_story_31050201_136_dialog_content = "Aku tidak keberatan melihat Dawn lebih bahagia meski hanya sedikit... Namun, kamu harus sangat berhati-hati!",
  ui_story_31050201_137_dialog_content = "Jangan khawatir! Joanie dan aku sudah membicarakannya, dan aku berjanji kami tidak akan membuat kembang api yang berbahaya!",
  ui_story_31050201_138_dialog_content = "Hmm... Begini, akan lebih mudah jika kalian meminta bantuanku dari awal. Kenapa semua harus sembunyi-sembunyi?",
  ui_story_31050201_139_dialog_content = "K-karena... Aku ingin membuat kejutan untuk Dawn.",
  ui_story_31050201_140_dialog_content = "Aku rasa jika aku memberitahumu, kamu akan segera memberi tahu yang lain...",
  ui_story_31050201_141_dialog_content = "Apakah Eve menganggapku seperti itu?...",
  ui_story_31050201_142_dialog_content = "Selain itu, kami tidak ingin mengecewakan siapa pun jika hasilnya buruk... Jadi, kami ingin memastikan semuanya sudah oke sebelum memberi tahu semua orang!",
  ui_story_31050201_143_dialog_content = "Jangan khawatir. Bahkan tanpa kembang api, aku yakin kita punya banyak cara lain untuk membahagiakan Dawn.",
  ui_story_31050201_144_dialog_content = "Untuk ukuran bocah seusiamu, kamu ini banyak tahu, Eve...",
  ui_story_31050201_145_dialog_content = "<color=#e8d9bb>Kamu mengulurkan tangan dan menepuk kepala Eve.</color>",
  ui_story_31050201_146_dialog_content = "Meski demikian, aku ingin acara ini sukses besar... Aku tidak akan gagal!",
  ui_story_31050201_147_dialog_content = "Aku juga akan membantu!",
  ui_story_31050201_X147_dialog_content = "Jangan menatapku seperti itu! Aku janji tidak akan bilang-bilang siapa pun!",
  ui_story_31050201_148_dialog_content = "Omong-omong, kapan kamu berencana untuk menunjukkan kembang api itu pada Dawn?",
  ui_story_31050201_149_dialog_content = "<color=#e8d9bb>Eve menutup bibirnya dengan jarinya.</color>",
  ui_story_31050201_150_dialog_content = "Aku belum bisa memberitahumu!",
  ui_story_31050201_151_dialog_content = "Lagi pula, ini masih kejutan besar!",
  ui_story_31050201_152_dialog_content = "Kamu masih mengira aku akan bilang siapa-siapa, ya...?",
  ui_story_31050201_153_dialog_content = "Mungkin hanya sedikit...",
  ui_story_31050201_154_dialog_content = "Meski aku masih sedikit khawatir... Aku memercayaimu, Eve. Aku tahu kamu tidak akan melakukan hal yang berbahaya!",
  ui_story_31050201_155_dialog_content = "Serahkan saja padaku! Kamu pasti juga akan sangat terkejut!",
  ui_story_31050601_1_dialog_content = "The Xth",
  ui_story_31050601_2_dialog_content = "Kontes Popularitas Rediesel Wrench",
  ui_story_31050601_3_dialog_content = "Panggung Kontes",
  ui_story_31050601_4_dialog_content = "<color=#e8d9bb>Tiga jam sebelum kontes...</color>",
  ui_story_31050601_5_dialog_content = "Lanjutkan latihan kostum set! Kru di belakang panggung, kemana mereka pergi?!",
  ui_story_31050601_6_dialog_content = "Kalian tidak bisa baca, ya? Kalian semua, berdiri di tempat! Kalau tidak, operator lampu sorotnya tak akan bisa mengikuti kalian!",
  ui_story_31050601_7_dialog_content = "Apa ada yang melihat Regina? Suruh dia ke belakang panggung untuk mengganti earpiece!!",
  ui_story_31050601_8_dialog_content = "Pemeriksaan mikrofon, satu-dua, satu-dua... Tes, tes, satu-dua-tiga...",
  ui_story_31050601_9_dialog_content = "Tenangkan diri, tarik napas... Tenangkan diri, tarik napas... Tenangkan diri, tarik napas... Aduh...",
  ui_story_31050601_10_dialog_content = "...",
  ui_story_31050601_11_dialog_content = "Wah, kontesnya sudah dimulai. Semua orang tampak sibuk.",
  ui_story_31050601_12_dialog_content = "<color=#e8d9bb>Bukk!!</color>",
  ui_story_31050601_13_dialog_content = "B-besar sekali kotak kembang api itu!!",
  ui_story_31050601_14_dialog_content = "Hei, tolong minggir. Nanti kamu terluka.",
  ui_story_31050601_15_dialog_content = "Ah! Eh, m-maaf...",
  ui_story_31050601_16_dialog_content = "Sebaiknya aku menunggu di tempat lain...",
  ui_story_31050601_17_dialog_content = "Fyuh... Ini sudah cukup jauh, 'kan?",
  ui_story_31050601_18_dialog_content = "Kalau dipikir-pikir lagi... Kenapa aku kemari, ya...?",
  ui_story_31050601_19_dialog_content = "...",
  ui_story_31050601_20_dialog_content = "Hmm?",
  ui_story_31050601_21_dialog_content = "Ayo, ayo, lakukan... yang terbaik? Tidak... Pertahankan dan...",
  ui_story_31050601_22_dialog_content = "Tidak, kedengarannya tidak cocok...",
  ui_story_31050601_23_dialog_content = "Ketemu.",
  ui_story_31050601_24_dialog_content = "...",
  ui_story_31050601_25_dialog_content = "Ehem.",
  ui_story_31050601_26_dialog_content = "Hah? S-siapa itu?",
  ui_story_31050601_27_dialog_content = "Aha! Sudah kuduga. Rupanya memang kamu, Eve!",
  ui_story_31050601_28_dialog_content = "PlayerName?! Oh... Benar, kamu juga ikut kontes...",
  ui_story_31050601_29_dialog_content = "Iya, aku kemari untuk melihat geladi bersih, tapi... sepertinya tak ada yang mengikuti arahan.",
  ui_story_31050601_30_dialog_content = "Maaf! Memang begitulah orang-orang di sini.",
  ui_story_31050601_31_dialog_content = "Tidak apa-apa. Ini bukan pertama kalinya aku berurusan dengan Rediesel Wrench, kok.",
  ui_story_31050601_32_dialog_content = "...",
  ui_story_31050601_33_dialog_content = "...",
  ui_story_31050601_34_dialog_content = "Anu... pakaianmu...",
  ui_story_31050601_35_dialog_content = "Ah! I-ini baru, lo. Kamu suka? Aku, anu... Saat kontes, aku ingin...",
  ui_story_31050601_36_dialog_content = "Kudengar ini pakaian spesial ini bisa meningkatkan kepercayaan diri, jadi aku...",
  ui_story_31050601_37_dialog_content = "Kamu ingin menghibur semua orang dan menyemangati mereka, Eve? Ide bagus! Belakangan ini kamu juga terlihat jauh lebih energik!",
  ui_story_31050601_38_dialog_content = "Benar! Karena belakangan ini aku merasa jauh lebih sehat, aku tak ingin terus memanfaatkan kebaikan hati semua orang... Jadi, kupikir ini cara yang tepat untuk membalas budi mereka!",
  ui_story_31050601_39_dialog_content = "Kenapa kamu tidak ikut kontesnya saja?",
  ui_story_31050601_40_dialog_content = "Yah, kalau aku ikut...",
  ui_story_31050601_41_dialog_content = "Whoo!",
  ui_story_31050601_42_dialog_content = "Yeaaaaah! Ayo, Eve!!!",
  ui_story_31050601_43_dialog_content = "Lihat, 'kan? Penampilannya sangat bagus! Itu bukan hanya seni, tapi juga keajaiban!",
  ui_story_31050601_44_dialog_content = "Jadi, jangan lupa memilih Eve, semuanya! ...Awas kalau tidak.",
  ui_story_31050601_45_dialog_content = "Siapa yang tidak berani?!",
  ui_story_31050601_46_dialog_content = "Yah, kemungkinan itu memang pasti, sih...",
  ui_story_31050601_47_dialog_content = "Iya, 'kan? Kadang kakakku bisa agak terbawa suasana...",
  ui_story_31050601_48_dialog_content = "Jadi, kuputuskan untuk tidak ikut kontes, dan menghibur semua orang saja!",
  ui_story_31050601_49_dialog_content = "Bagaimana menurutmu tentang pakaianku?",
  ui_story_31050601_50_option_content = "Bagus sekali!",
  ui_story_31050601_51_dialog_content = "Aku belum pernah melihat gaya pakaian yang seperti ini di seantero Astra! Sangat mencolok mata!",
  ui_story_31050601_52_dialog_content = "Desain dan kepraktisannya sangat cocok untuk pemandu sorak!",
  ui_story_31050601_53_dialog_content = "Aku jadi penasaran siapa yang menciptakan pakaian ini...",
  ui_story_31050601_54_dialog_content = "Sama! Aku juga setuju denganmu; pakaian ini sangat bagus!",
  ui_story_31050601_55_dialog_content = "Kudengar harganya juga sangat mahal!",
  ui_story_31050601_56_option_content = "Masih bisa disempurnakan.",
  ui_story_31050601_57_dialog_content = "Desainnya baru; aku belum pernah melihat yang seperti itu di seluruh Astra...",
  ui_story_31050601_58_dialog_content = "Tapi, kalau mau dikenakan di gurun, kurasa seharusnya lebih tertutup agar tidak terbakar sinar matahari.",
  ui_story_31050601_59_dialog_content = "Lalu kalau kamu jatuh, lutut dan pergelangan kakimu...",
  ui_story_31050601_60_dialog_content = "K-kamu benar-benar memikirkan segalanya, ya, PlayerName? Yah, kurasa tidak apa-apa kalau hanya dikenakan sesekali, sih.",
  ui_story_31050601_61_dialog_content = "Lagi pula, tidak mudah mendapatkannya. Ini sangat mahal, lo!",
  ui_story_31050601_62_dialog_content = "Bukan Jomu yang menjualnya, 'kan?",
  ui_story_31050601_63_dialog_content = "Bukan! Sebenarnya, Joanie dan yang lain mencurinya dari Caravan Umbraton!",
  ui_story_31050601_64_dialog_content = "Sial! Para anggota Rediesel keparat itu berhasil kabur lagi! Cepat periksa apa saja barang kita yang hilang kali ini!",
  ui_story_31050601_65_dialog_content = "Celaka... Pakaian olahraga mungil yang manis itu hilang! Dasar monster!",
  ui_story_31050601_66_dialog_content = "Rediesel Wrench... Kuharap mereka bisa memanfaatkannya dengan baik!",
  ui_story_31050601_67_dialog_content = "Eh, apa itu yang ada di tangan kananmu?",
  ui_story_31050601_68_dialog_content = "Oh, ini? Tiny One dan Sinsa membantuku membuatnya, jadi aku punya sesuatu yang cocok dengan outfit baruku!",
  ui_story_31050601_69_dialog_content = "Kelihatannya bagus sekali, tapi... Apa fungsi <color=#FFB400>tombol</color> itu?",
  ui_story_31050601_70_dialog_content = "Y-yang ini?",
  ui_story_31050601_71_dialog_content = "Anu... Ini alat pertahanan diri yang Sinsa pasang...",
  ui_story_31050601_72_dialog_content = "Hah?",
  ui_story_31050601_73_dialog_content = "Katanya, kalau aku dalam bahaya, aku hanya perlu menekan tombol ini, lalu dia akan...",
  ui_story_31050601_74_dialog_content = "Perhatian! Perhatian! Kalau masih ada yang belum melakukan geladi bersih, kemarilah sekarang! Waktunya hampir habis!",
  ui_story_31050601_75_dialog_content = "Aku membawa peralatan baru itu, Odi! Di mana harus kuparkir mobilku?",
  ui_story_31050601_76_dialog_content = "Parkir saja di kepalamu yang kosong dan gendut itu!",
  ui_story_31050601_77_dialog_content = "Apa-apaan?!",
  ui_story_31050601_78_dialog_content = "Gawat, sudah hampir waktunya!",
  ui_story_31050601_79_dialog_content = "Aku harus cepat-cepat berlatih gerakan pemandu sorak! Kamu bisa membantuku sedikit?",
  ui_story_31050601_80_dialog_content = "T-tapi, aku juga harus pergi...",
  ui_story_31050601_81_dialog_content = "Mana yang lebih bagus? <color=#FFB400>\"Sinsa, Sinsa, kamu sangat hebat\"</color> atau...",
  ui_story_31050601_82_dialog_content = "<color=#FFB400>\"Ayo, Rediesel! Kita memang hebat!\"</color>?",
  ui_story_31050601_83_dialog_content = "...",
  ui_story_31050601_84_dialog_content = "... Meskipun terasing dari dunia luar selama tujuh belas tahun, menurutku itu tidak bagus...",
  ui_story_31050601_85_dialog_content = "B-benarkah? Tapi, aku sudah memikirkannya sejak lama...",
  ui_story_31050601_86_dialog_content = "Bagaimana kalau kamu sambil melakukan gerakan yang manis atau semacamnya?",
  ui_story_31050601_87_dialog_content = "Begini?",
  ui_story_31050601_88_dialog_content = "<size=40>Hei!</size>",
  ui_story_31050601_89_dialog_content = "<size=40>\"Sinsa, Sinsa, kamu sangat hebat!\"</size>",
  ui_story_31050601_90_dialog_content = "<color=#e8d9bb>Ta-ra!</color>",
  ui_story_31050601_91_dialog_content = "(Manis sekali...)",
  ui_story_31050601_92_dialog_content = "Atau mungkin harus kutambahkan gerakan lagi? Hmm... Apa yang akan dilakukan Barbara, ya?",
  ui_story_31050601_93_dialog_content = "<size=40>Hei! Hei!</size>",
  ui_story_31050601_94_dialog_content = "<size=40>Yo!!</size>",
  ui_story_31050601_95_dialog_content = "<size=40>\"Ayo, Rediesel! Kita memang hebat!\"</size>",
  ui_story_31050601_96_dialog_content = "<size=40>\"Ayo, Rediesel! Kita memang hebat!\"</size>",
  ui_story_31050601_97_dialog_content = "<size=40>Ayo, semuanya!</size>",
  ui_story_31050601_98_dialog_content = "(Ini terlalu manis!!!)",
  ui_story_31050601_99_dialog_content = "<size=40>\"Ayo, Rediesel! Kita memang hebat!\"</size>",
  ui_story_31050601_100_dialog_content = "<size=40>\"Ayo, Rediesel! Kita memang hebat!\"</size>",
  ui_story_31050601_101_dialog_content = "<size=40>Lebih keras! Angkat tangan ke udara!</size>",
  ui_story_31050601_102_dialog_content = "<size=45>\"Ayo, Rediesel! Kita memang hebat!!\"</size>",
  ui_story_31050601_103_dialog_content = "Kalian yang di belakang, ayo berdiri dan ikut bersorak!",
  ui_story_31050601_104_dialog_content = "<size=48>\"Ayo, Rediesel! Kita memang hebat!!!\"</size>",
  ui_story_31050601_105_dialog_content = "Ayo kita meriahkan gurun ini, teman-teman! Whoo!",
  ui_story_31050601_106_dialog_content = "<anim type=Shake><size=51>\"Ayo, Rediesel! Kita memang hebat!!!!!\"</size></anim>",
  ui_story_31050601_107_dialog_content = "<size=40>Hei! Hei!</size>",
  ui_story_31050601_108_dialog_content = "<size=40>Hei! Hei!</size>",
  ui_story_31050601_109_dialog_content = "<size=40>Oww!!</size>",
  ui_story_31050601_110_dialog_content = "<color=#e8d9bb>Dug!</color>",
  ui_story_31050601_111_dialog_content = "Oww!! ...Sebentar... \"Oww\"?",
  ui_story_31050601_112_dialog_content = "Hah? Eve?",
  ui_story_31050601_113_dialog_content = "...PlayerName...",
  ui_story_31050601_114_dialog_content = "Argh...",
  ui_story_31050601_115_dialog_content = "Oh tidak... Eve! Kamu jatuh! Kau baik-baik saja?",
  ui_story_31050601_116_dialog_content = "A-aku tidak apa-apa! Aku hanya sedikit terbawa suasana...",
  ui_story_31050601_117_dialog_content = "Kenapa ada lubang di sini...?",
  ui_story_31050601_118_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_31050601_119_dialog_content = "Suara apa itu?",
  ui_story_31050601_120_dialog_content = "Eh... Aduh.",
  ui_story_31050601_121_dialog_content = "Aku...",
  ui_story_31050601_122_dialog_content = "Aku tak sengaja menekan <color=#FFB400>tombol</color> itu!",
  ui_story_31050601_123_dialog_content = "Lari, PlayerName!",
  ui_story_31050601_124_dialog_content = "Lari? Kenapa...?",
  ui_story_31050601_125_dialog_content = "<size=45><color=#e8d9bb>Wuuss!!!</color></size>",
  ui_story_31050601_126_dialog_content = "Haaaaaa!!!",
  ui_story_31050601_127_dialog_content = "...!!!",
  ui_story_31050601_128_dialog_content = "Dengarlah!",
  ui_story_31050601_129_dialog_content = "Sinsa, penjaga Eve, telah datang!",
  ui_story_31050601_130_dialog_content = "Katakan...",
  ui_story_31050601_131_dialog_content = "Apa kamu yang melukai adikku?!",
  ui_story_31050601_132_dialog_content = "...",
  ui_story_31050601_133_dialog_content = "(Aku sampai tak bisa berkata-kata.)",
  ui_story_31050601_134_dialog_content = "(Apa ini karena sangat mendadak? Aku benar-benar lengah...)",
  ui_story_31050601_135_dialog_content = "(Bukan... Bukan itu.)",
  ui_story_31050601_136_dialog_content = "(Alasan sebenarnya mengapa saya tidak bisa berkata-kata sekarang adalah...)",
  ui_story_31050601_137_dialog_content = "<size=45>Dari mana kamu muncul, Sinsa?!?!</size>",
  ui_story_31050602_1_dialog_content = "<color=#e8d9bb>Cicit, cicit—</color>",
  ui_story_31050602_2_dialog_content = "Perlahan sekarang, Eve! Tanah di sini tidak begitu rata!",
  ui_story_31050602_3_dialog_content = "Tapi tempat ini sangat indah! Lihat saja sinar matahari yang hangat... dan rasakan angin sepoi-sepoi... Ah! Cuacanya benar-benar sempurna!",
  ui_story_31050602_4_dialog_content = "Ada begitu banyak bunga dan tanaman indah yang belum pernah saya lihat sebelumnya!",
  ui_story_31050602_5_dialog_content = "Kamu sedang sangat bersemangat hari ini... Apakah kamu merasa lebih baik akhir-akhir ini?",
  ui_story_31050602_6_dialog_content = "Jauh lebih baik! Kakakku sudah merawatku dengan baik, tetapi biasanya aku hanya tinggal di kamarku sepanjang hari dan itu sangat membosankan...",
  ui_story_31050602_7_dialog_content = "Maksud kamu, kamu menyelinap keluar untuk hang out bersamaku hari ini?",
  ui_story_31050602_8_dialog_content = "Tidak, saya sudah memberitahunya sebelum saya keluar!",
  ui_story_31050602_9_dialog_content = "Eve? Kenapa kamu pakai outfit itu? Kamu mau ke mana?",
  ui_story_31050602_10_dialog_content = "Aku mau main sama PlayerName! Sampai jumpa!",
  ui_story_31050602_11_dialog_content = "Hei! Jam berapa kamu ketemu dia? Ke mana kamu berdua pergi?",
  ui_story_31050602_12_dialog_content = "<size=45>Ingat untuk kembali tepat waktu untuk makan malam!</size>",
  ui_story_31050602_13_dialog_content = "Dia bilang itu baik!",
  ui_story_31050602_14_dialog_content = "Kuharap begitu... Ngomong-ngomong, pakaianmu sangat bagus!",
  ui_story_31050602_15_dialog_content = "Mereka bergaya, pas dengan sempurna, dan yang paling penting—",
  ui_story_31050602_16_dialog_content = "Kamu terlihat sangat bahagia di dalamnya!",
  ui_story_31050602_17_dialog_content = "Saya pikir outfit ini juga bagus! Saya ingin membuat lemari pakaian super besar di kamar saya, diisi dengan berbagai jenis atasan dan rok yang cantik!",
  ui_story_31050602_18_dialog_content = "Maukah kamu pergi bersamaku ke Umbraton waktu berikutnya untuk memilih lebih banyak lagi?",
  ui_story_31050602_19_dialog_content = "Oke! Itu kesepakatan!",
  ui_story_31050602_20_dialog_content = "Ayo pergi, aku masih ingin melihat bukit kecil di depan sana!",
  ui_story_31050602_21_dialog_content = "Fyuh…",
  ui_story_31050602_22_dialog_content = "Apakah kamu lelah, Eve? Apakah tubuhmu...",
  ui_story_31050602_23_dialog_content = "Tubuhku baik-baik saja... Jangan khawatir! Mari kita istirahat lima menit.",
  ui_story_31050602_24_dialog_content = "Oke! Aku bawa beberapa makanan! Ada kantin di sini juga. Minum air dulu, dan aku akan menyebarkan tikar piknik.",
  ui_story_31050602_25_dialog_content = "Terima kasih. Apakah kamu membuat semua ini sendiri? Wow! Kita punya sandwich, salad, dan banyak lagi!",
  ui_story_31050602_26_dialog_content = "Oh, apakah wortel ini seharusnya dipotong menjadi bentuk bunga fajar?! Itu sangat perhatian dari kamu!",
  ui_story_31050602_27_dialog_content = "Y-Ya, baiklah... Haha...",
  ui_story_31050602_28_dialog_content = "... Dan sekarang, sentuhan... terakhir!",
  ui_story_31050602_29_dialog_content = "PlayerName, berhenti mengiris wortel! Kamu sudah menghabiskan banyak keranjang... Beri sedikit perhatian pada pengeluaran makanan kita untuk minggu depan, ya?",
  ui_story_31050602_30_dialog_content = "Jangan khawatir, aku pastikan aku makan semuanya!",
  ui_story_31050602_31_dialog_content = "Pokoknya, saya membuat semua ini sendiri. Silakan lanjutkan dan coba...",
  ui_story_31050602_32_dialog_content = "Ya! Mari kita duduk dulu!",
  ui_story_31050602_33_dialog_content = "Baiklah!",
  ui_story_31050602_34_dialog_content = "Rumput itu sangat lembut dan harum... Aromanya luar biasa saat bercampur dengan bau sinar matahari.",
  ui_story_31050602_35_dialog_content = "Apakah sinar matahari memiliki aroma?",
  ui_story_31050602_36_dialog_content = "Tentu saja! Tutup mata Anda dan biarkan sinar matahari menyapu wajah Anda.",
  ui_story_31050602_37_dialog_content = "Hmm... Ini hangat. Even dengan mata tertutup, saya masih bisa melihat cahaya emasnya.",
  ui_story_31050602_38_dialog_content = "Kamu suka berjemur di bawah matahari, bukan...",
  ui_story_31050602_39_dialog_content = "Ya, sensasi hangatnya cahaya matahari di tubuh membuatku merasa... hidup.",
  ui_story_31050602_40_dialog_content = "Dan jika saya berbaring seperti ini untuk beberapa saat, saya bisa dengan mudah terlelap dalam tidur siang yang menyegarkan tanpa menyadarinya!",
  ui_story_31050602_41_dialog_content = "Saya mulai merasa mengantuk juga. Tapi kita harus ingat untuk kembali tepat waktu, karena saudara Anda mungkin akan khawatir saat mulai gelap.",
  ui_story_31050602_42_dialog_content = "Hmm! Jangan khawatir, aku tidak akan membuat masalah hari ini!",
  ui_story_31050602_43_dialog_content = "(Seperti yang Eve katakan, berbaring di rumput dan tidur siang yang nyaman sangat menenangkan.)",
  ui_story_31050602_44_dialog_content = "(Hmm, sudah lama sekali aku tidak bersantai dan beristirahat dengan baik, dan sudah lama juga sejak terakhir kali aku mencoba menghirup aroma di sekitarku.)",
  ui_story_31050602_45_dialog_content = "<color=#e8d9bb>Kresek...</color>",
  ui_story_31050602_46_dialog_content = "Eve?",
  ui_story_31050602_47_dialog_content = "PlayerName, Aku di sini!",
  ui_story_31050602_48_dialog_content = "Lihat, ini adalah...",
  ui_story_31050602_49_dialog_content = "Hati-hati, ini sangat rapuh. Bunga ini disebut <color=#FFB400>dandelion</color>. Benihnya terbawa angin dan terbang jauh.",
  ui_story_31050602_50_dialog_content = "Benarkah? Seberapa jauh mereka terbang dan kemana mereka pergi?",
  ui_story_31050602_51_dialog_content = "Tergantung pada arah angin dan seberapa kencang angin tersebut. Terkadang mereka terbang ke padang rumput dan kebun di sekitar, dan terkadang mereka terbang ke gunung, sungai, dan danau yang jauh.",
  ui_story_31050602_52_dialog_content = "Oh, saya ingat sebuah cerita tentang ini!",
  ui_story_31050602_53_dialog_content = "Beberapa orang mengatakan bahwa jika kamu mengucapkan <color=#FFB400>permohonan</color> pada dandelion yang utuh dan meniupnya, permohonanmu akan terkabul saat biji pertama mendarat.",
  ui_story_31050602_54_dialog_content = "Serius! Aku ingin mencobanya!",
  ui_story_31050602_55_dialog_content = "... Keinginan apa yang harus aku buat? Kau punya saran?",
  ui_story_31050602_56_option_content = "Harapkan hal yang paling kamu inginkan.",
  ui_story_31050602_57_dialog_content = "Apakah ada sesuatu yang spesial yang kamu inginkan?",
  ui_story_31050602_58_dialog_content = "Oh, benar! Saya ingin tinggal bersama saudara saya, Dawn, PlayerName, dan setiap orang selamanya!",
  ui_story_31050602_59_dialog_content = "Dan kemudian kita akan bahagia setiap hari... Even meskipun kita tidak mencapai sesuatu yang sangat penting, kita bisa menjalani hidup yang sederhana dan bahagia.",
  ui_story_31050602_60_dialog_content = "Itu juga yang saya inginkan.",
  ui_story_31050602_61_dialog_content = "Benar! Jadi, kita memang memiliki hubungan yang dalam! Apakah ini keinginan kita bersama?",
  ui_story_31050602_62_dialog_content = "Ya, tapi kamu bisa meniup dandelion karena kamu adalah suara resmi dari keinginan kita sekarang.",
  ui_story_31050602_63_dialog_content = "Ingat saja bahwa dandelion saja tidak bisa membuat keinginanmu menjadi kenyataan. Kita masih perlu bekerja sama dan bekerja keras!",
  ui_story_31050602_64_dialog_content = "Aku mengerti. Baiklah, aku akan meledakkannya sekarang!",
  ui_story_31050602_65_option_content = "Hidup di saat ini.",
  ui_story_31050602_66_dialog_content = "Saya benar-benar ingin momen bahagia ini bertahan selamanya.",
  ui_story_31050602_67_dialog_content = "Boleh sekali! Bayangkan jika matahari tidak pernah terbenam, aku, Sinsa, Dawn, PlayerName, dan semua orang lain... Kita bisa pergi jalan-jalan panjang dan piknik bersama, selamanya!",
  ui_story_31050602_68_dialog_content = "Saya tidak yakin punya stamina untuk itu.",
  ui_story_31050602_69_dialog_content = "Hahaha, ya! Tapi kalau begitu kamu akan selalu bahagia, tanpa beban di dunia ini!",
  ui_story_31050602_70_dialog_content = "Ya, tanpa beban di dunia!",
  ui_story_31050602_71_dialog_content = "Hei, kamu mengolok-olok aku?!",
  ui_story_31050602_72_dialog_content = "Saya sedang membuat keinginan bersama. Ingatlah bahwa hanya dandelion saja tidak bisa membuat keinginan Anda menjadi kenyataan. EveUsaha dan ketekunan setiap orang juga memiliki peran besar dalam hal ini.",
  ui_story_31050602_73_dialog_content = "Tidak peduli apa yang dikatakan orang lain, selama kita berusaha untuk bahagia, kita bisa hidup bahagia setiap hari.",
  ui_story_31050602_74_dialog_content = "Tidak peduli apa yang dikatakan orang atau bahkan apa yang diputuskan langit di atas...",
  ui_story_31050602_75_dialog_content = "Kau benar. Bahkan takdir pun tak akan menghalangi keinginan kita!",
  ui_story_31050602_76_dialog_content = "<color=#e8d9bb>Eve menutup matanya dan diam-diam mengucapkan keinginannya di hati, lalu mengambil napas lembut.</color>",
  ui_story_31050602_77_dialog_content = "<color=#e8d9bb>Kabut putih terbawa angin seperti tak terhitung kata yang tertulis di angin.</color>",
  ui_story_31050602_78_dialog_content = "<color=#e8d9bb>Mungkin salah satu keinginannya telah menjadi kenyataan, tetapi masih ada lebih banyak yang akan datang, masing-masing terbawa oleh biji-bijian dandelion.</color>"
}
return config
